// D e' DISCRETA: lo slider scatta all'intero al rilascio. La direttiva := si
// legge SOLO dallo scriptCode, quindi va scritta qui (la chiave JSON
// "discreteConstants" non sopravvive a un salvataggio dall'app).
D := int(1,20);

// N sullo slider D, intero fra 1 e 20.
float N = clamp(floor(D + 0.5), 1.0, 20.0);

// Le sezioni mesh sono testo statico: sono sempre 20. Le copie oltre N si
// collassano in un punto (fattore 0) invece di essere disegnate: una mesh
// degenere non produce area visibile.
float live = step(mesh, N - 0.5);

// Geometria del cerchio di Villarceau. B < A perche' la radice sia reale.
float bb = clamp(B, 0.0, A - 0.001);
float cc = sqrt(A * A - bb * bb) / A;
float ss = bb / A;

// Tubo di raggio C attorno all'anima, nel frame di Frenet del cerchio (curva
// piana: binormale costante, il frame non torce).
float R = A - C * cos(v);

float px = (R * cc * cos(u) - C * ss * sin(v)) * live;
float py = (bb + R * sin(u)) * live;
float pz = (R * ss * cos(u) + C * cc * sin(v)) * live;

// LO SCORRIMENTO: angolo comune theta(t) sommato allo sfasamento della copia.
// E' lo stesso theta per tutte -> moto rigido -> distanze invariate.
// E governa la velocita' (E = 1 -> un giro completo in circa 12.6 s).
float theta = 0.5 * E * t;
float ang = 6.28318531 * mesh / N + theta;
float ca = cos(ang);
float sa = sin(ang);

// Il corpo diventa il body di vec4 getRawPosition(...): il return DEVE essere
// vec4, con la quarta componente (coordinata 4D) a 0 per una superficie in R^3.
return vec4(
    px * ca - py * sa,
    px * sa + py * ca,
    pz,
    0.0
);
